INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Compliment a Stranger or Peer', 'Micro-moments of positivity resonance strengthen our sense of community belonging.', 'Give one genuine compliment today—to a barista, a coworker, or a classmate. Notice how their expression shifts.', 13, 20, '2 mins', 'ph-smiley', 'free', TRUE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Box Breathing Reset', 'Used by first responders to regain calm and cognitive control under high stress.', 'Visualize a square. Inhale for 4 counts up the left side, hold for 4 across the top, exhale for 4 down the right, and hold for 4 across the bottom. Repeat 4 times.', 14, 20, '3 mins', 'ph-square', 'free', FALSE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Curate Your Feed', 'Protecting your attentional diet prevents passive social comparison.', 'Open your most-used social app and mute or unfollow 3 accounts that consistently make you feel inadequate, drained, or unnecessarily angry.', 15, 20, '5 mins', 'ph-scissors', 'free', TRUE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Savoring Ritual', 'Savoring extends the duration of positive emotions and anchors you in the present.', 'During your next cup of tea, coffee, or snack, eat or drink the first three sips/bites at half speed. Notice the temperature, aroma, and texture.', 16, 30, '5 mins', 'ph-coffee', 'free', FALSE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Done List (Instead of To-Do)', 'Celebrating small wins builds self-efficacy and momentum.', 'Write down 5 things you have already accomplished this week—even small wins like answering an email, cooking a meal, or showing up on a tough day.', 17, 20, '4 mins', 'ph-list-checks', 'free', TRUE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Neck & Eye Release', 'Relieves ocular strain and trapezius tension caused by screen posture.', 'Follow the 20-20-20 rule: look at something 20 feet away for 20 seconds, then gently tilt your right ear toward your right shoulder for 20 seconds. Switch sides.', 18, 20, '3 mins', 'ph-eye', 'free', FALSE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Permission to Say ''No''', 'Every intentional ''no'' creates space for a meaningful ''yes'' to your wellbeing.', 'Identify one obligation, tab, or expectation you are carrying that isn''t truly mandatory. Give yourself permission to drop, postpone, or simplify it.', 19, 20, '5 mins', 'ph-shield-check', 'free', TRUE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Curiosity Rabbit Hole', 'Intrinsic curiosity refreshes mental energy and reminds you that learning is playful.', 'Spend 10 minutes reading or watching something purely out of curiosity—unrelated to work or productivity. How do whales sleep? How is glass made?', 20, 20, '10 mins', 'ph-compass', 'free', FALSE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Evening Worry Parking Lot', 'Creates a psychological boundary between daytime problem-solving and rest.', 'Write down any worry you have about tomorrow on a note. Fold it up and tell yourself: ''I have captured this; I will pick it up at 9 AM tomorrow.''', 21, 20, '4 mins', 'ph-archive-box', 'free', TRUE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Body Scan Check-In', 'Improves interoceptive awareness—your ability to read your body''s early stress signals.', 'Close your eyes and mentally scan from your forehead down to your toes. Notice where you are holding tightness without judging it, and breathe warmth into that area.', 22, 20, '5 mins', 'ph-person-simple-tai-chi', 'free', FALSE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Letter to Future You', 'Strengthens temporal connection with your future self, improving long-term decision-making.', 'Write a 3-sentence note of encouragement to yourself one month from today. What habit or mindset from this calendar do you want to keep alive?', 23, 20, '5 mins', 'ph-envelope-simple-open', 'free', TRUE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Celebrate Your Journey', 'Consciously marking endings consolidates positive memories and habit identity.', 'Look back at the doors you''ve opened and completed. Take a moment to acknowledge the time you carved out for your mental wellbeing. Leave your final reflection below!', 24, 30, '5 mins', 'ph-trophy', 'free', FALSE FROM calendars c WHERE c.title = 'Mindfulness & Self-Help' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Lunge Walk', 'Lunges train legs and balance together.', 'Take 12 long lunging steps forward, then 12 back. Keep your front knee over your ankle. Do 3 rounds.', 13, 20, '8 mins', 'ph-footprints', 'free', TRUE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Core Circuit', 'A strong core steadies everything you do.', 'Do 30 seconds each of dead bugs, bicycle crunches and side planks per side. Rest 30 seconds. Repeat 3 times.', 14, 20, '10 mins', 'ph-timer', 'free', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Tempo Run Intervals', 'Mixing paces trains speed and stamina.', 'Jog 3 minutes easy, run 2 minutes at a hard but steady pace. Repeat 4 times and walk to cool down.', 15, 40, '20 mins', 'ph-heartbeat', 'premium', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Wall Sit Challenge', 'Isometric holds build leg endurance.', 'Hold a wall sit with thighs parallel to the floor for 40 seconds. Rest 30 seconds. Repeat 5 times.', 16, 20, '6 mins', 'ph-arrow-fat-line-down', 'free', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Shoulder & Back Strength', 'Posture improves when the upper back is strong.', 'Do 3 sets of 12 superman holds, 12 reverse snow angels and 10 pike push-ups with 40 seconds rest.', 17, 20, '12 mins', 'ph-barbell', 'free', TRUE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Pyramid Strength Session', 'Pyramids add volume without losing form.', 'Do squats and push-ups in a pyramid: 4, 6, 8, 10, 8, 6, 4 reps of each. Rest 20 seconds between sets.', 18, 40, '25 mins', 'ph-barbell', 'premium', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Nature Walk & Notice', 'Time outdoors lifts mood and eases stress.', 'Walk somewhere green for 15 minutes. Find five different colours and listen for three separate sounds.', 19, 20, '15 mins', 'ph-footprints', 'free', TRUE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Dance Break', 'Movement you enjoy keeps you coming back.', 'Pick three songs you love and dance freely to all of them. No rules, just keep moving.', 20, 20, '10 mins', 'ph-music-notes', 'free', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Hill or Stair Repeats', 'Climbing builds power quickly.', 'Find a hill or stairs. Climb for 45 seconds at a strong effort and walk down. Repeat 8 times.', 21, 40, '15 mins', 'ph-stairs', 'premium', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Hip & Glute Stretch Flow', 'Open hips reduce lower-back strain.', 'Hold pigeon pose, figure-four and low lunge for 45 seconds per side. Breathe slowly the whole time.', 22, 20, '10 mins', 'ph-flower-lotus', 'free', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Weekly Movement Plan', 'A simple plan makes consistency easy.', 'Pick three days and a 20-minute activity for each. Write them down and tell someone about your plan.', 23, 20, '10 mins', 'ph-notebook', 'free', TRUE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Active Recovery & Review', 'Recovery is part of training.', 'Do a gentle walk and stretch, then write down what felt strongest this calendar and your next fitness goal.', 24, 20, '10 mins', 'ph-leaf', 'free', FALSE FROM calendars c WHERE c.title = 'Fitness Challenge' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Weak Foot Passing', 'A reliable weaker foot makes you unpredictable.', 'Play 40 passes against a wall using only your weaker foot, then 20 first-time passes. Count your clean receptions.', 13, 30, '15 mins', 'ph-arrows-left-right', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'First Touch Control', 'A good first touch buys you time.', 'Throw the ball up or bounce it off a wall and control it with thigh, chest and foot. Aim for 10 controlled touches in a row.', 14, 30, '12 mins', 'ph-soccer-ball', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Turns and Feints', 'Changing direction beats defenders.', 'Practise the drag-back, Cruyff turn and step-over 10 times each, first slowly and then at match pace.', 15, 30, '15 mins', 'ph-path', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Crossing Practice', 'Good delivery creates chances.', 'Hit 15 crosses into a marked area from the wing, with both feet if you can. Note how many land in the target zone.', 16, 30, '20 mins', 'ph-target', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Heading Technique', 'Safe heading technique wins aerial duels.', 'Use a light ball. Practise standing headers against a wall, using your forehead and keeping your eyes open.', 17, 30, '10 mins', 'ph-soccer-ball', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Goalkeeping Basics', 'Understanding the keeper helps every player.', 'Practise diving saves to each side, catching with W-shaped hands and getting up quickly. Do 10 per side.', 18, 30, '15 mins', 'ph-hand-grabbing', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Speed and Agility Cones', 'Quick changes of direction win loose balls.', 'Set 4 cones in a square 5 metres apart. Sprint, shuffle, backpedal and shuffle round it. Do 8 rounds.', 19, 30, '15 mins', 'ph-lightning', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Understanding Formations', 'Shape and roles decide how teams play.', 'Draw a 4-4-2 and a 4-3-3. Write one job for each position and one strength of each shape.', 20, 30, '20 mins', 'ph-television', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'One-Touch Passing Patterns', 'Fast passing moves defenders out of position.', 'With a partner or wall, play passing triangles using one touch only. Keep going for 3 minutes without losing the ball.', 21, 30, '20 mins', 'ph-arrows-left-right', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Pressing and Tackling Drill', 'Winning the ball back quickly changes games.', 'Practise closing down a partner at an angle, staying low and timing a clean tackle. Swap roles after 10 attempts.', 22, 30, '15 mins', 'ph-users-three', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Penalty Routine', 'A calm routine beats pressure.', 'Take 10 penalties using the same routine each time: pick a corner, breathe out, strike. Record how many you score.', 23, 30, '15 mins', 'ph-flag', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Full Match Review', 'Reviewing play turns experience into learning.', 'Replay a match you took part in or watched. Note three things that worked and three things to improve next week.', 24, 30, '20 mins', 'ph-notebook', 'premium', FALSE FROM calendars c WHERE c.title = 'Football Skills Calendar' ON CONFLICT (calendar_id, day_number) DO NOTHING;
